# Numerical derivative using finite differences
def diff(func, x, n=1):
    h = 1e-5
    if n == 1:
        return (func(x+h) - func(x-h)) / (2*h)
    elif n == 2:
        return (func(x+h) - 2*func(x) + func(x-h)) / h**2
